function speakProfessor(text){if(!window.speechSynthesis)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='es-AR';utterance.rate=exam.speed==='rapida'?1.08:exam.speed==='sobrepensada'?.92:.98;const voices=window.speechSynthesis.getVoices();const chosen=voices.find(v=>v.lang==='es-AR')||voices.find(v=>v.lang.startsWith('es'));if(chosen)utterance.voice=chosen;window.speechSynthesis.speak(utterance)}
async function recordAnswer(){if(exam.recording){recorder?.stop();return}if(exam.busy)return;window.speechSynthesis?.cancel();try{recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});if(!examElement('exam-state')){recordStream.getTracks().forEach(t=>t.stop());return}const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime,audioBitsPerSecond:64000}:{audioBitsPerSecond:64000});const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{clearInterval(recordTimer);recordStream?.getTracks().forEach(t=>t.stop());exam.recording=false;if(exam.blobURL)URL.revokeObjectURL(exam.blobURL);exam.blob=new Blob(chunks,{type:recorder.mimeType});if(exam.blob.size>2900000){exam.blob=null;exam.error='La grabación es demasiado grande. Grabá una respuesta más breve.'}else if(exam.blob.size<200){exam.blob=null;exam.error='No se capturó audio. Probá de nuevo.'}else{exam.blobURL=URL.createObjectURL(exam.blob);exam.error='';window.startRecordedTranscription?.()}updateExam()};exam.recording=true;exam.seconds=0;exam.error='';recorder.start(1000);recordTimer=setInterval(()=>{exam.seconds++;if(exam.seconds>=90&&recorder.state==='recording')recorder.stop();updateExam()},1000);updateExam()}catch(e){recordStream?.getTracks().forEach(t=>t.stop());exam.error=e.name==='NotAllowedError'?'No se habilitó el micrófono. Permitilo desde tu navegador o respondé por escrito.':'No se pudo abrir el micrófono. Revisá que esté conectado o respondé por escrito.';updateExam()}}
