function encodeAudio(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)})}
async function askExamOnce(action){if(exam.busy||exam.recording)return;const field=examElement('exam-text');const text=field?.value.trim()||'';if(action==='answer'&&!text&&!exam.blob&&!exam.image){exam.error='Escribí, grabá o adjuntá una respuesta antes de enviarla.';updateExam();return}const sentAudioText=exam.recordedTranscript;const sentPlanToken=exam.planToken;const sentImage=action==='answer'&&exam.includeVisual?exam.image:null;const encodedBytes=(sentBlob)=>sentBlob?Math.ceil(sentBlob.size/3)*4:0;if(sentImage&&encodedBytes(sentImage)+encodedBytes(exam.blob)>3300000){exam.error='La imagen y la grabación juntas superan el límite. Reducí el tamaño de una o respondé por escrito.';updateExam();return}exam.busy=true;exam.error='';window.speechSynthesis?.cancel();updateExam();const sentBlob=action==='start'?null:exam.blob;try{let audio=null;if(sentBlob)audio={mimeType:sentBlob.type.split(';')[0],data:await encodeAudio(sentBlob)};let image=null;if(sentImage)image={mimeType:sentImage.type,data:await encodeAudio(sentImage)};examAbort=new AbortController();const timeout=setTimeout(()=>examAbort.abort(),65000);let response;try{response=await fetch('/api/exam',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,subject:exam.subject||currentSubject,unit:exam.unit,includeVisual:exam.includeVisual,level:exam.level,history:exam.history.slice(-16),speed:exam.speed,planToken:exam.planToken,depth:exam.depth,scope:exam.scope,loop:exam.loop,memory:exam.messages.filter(m=>m.role==='model').flatMap(m=>m.data.omissions||[]).slice(-8),text:action==='start'?'':text,audio,image}),signal:examAbort.signal})}finally{clearTimeout(timeout)}let data;try{data=await response.json()}catch{throw Error('El servidor no devolvió una respuesta válida. Reintentá en unos segundos.')}if(!response.ok)throw Error(data.error||'No se pudo consultar al profesor.');if(data.learningProgress){maqAccount.progress=data.learningProgress;updateAccountUI()}if(typeof data.speech!=='string')throw Error('El profesor devolvió una respuesta incompleta.');window.acceptDeferredResult?.(action,data,{text,audio,image,audioText:sentAudioText,planToken:sentPlanToken});if(action==='start')exam.history.push({role:'user',text:'Comenzar examen oral.'});else{const answerBase=audio?[text?'Texto escrito: '+text:'',sentAudioText?.text?'Transcripción independiente: '+sentAudioText.text:data.transcript?'Transcripción (Gemini): '+data.transcript:'[Audio guardado; transcripción pendiente]'].filter(Boolean).join('\n\n'):text||(sentImage?'':'Solicito finalizar el examen.');const answer=sentImage?(answerBase+'\n[Imagen adjunta: '+sentImage.name+']').trim():answerBase;if(text||audio||sentImage){exam.messages.push({role:'user',text:answer,writtenText:text,hadAudio:!!audio,audioText:sentAudioText,geminiTranscript:audio?data.transcript||'':''});exam.history.push({role:'user',text:answer})}else exam.history.push({role:'user',text:'Finalizar y evaluar el examen.'})}if(data.planToken)exam.planToken=data.planToken;if(data.planProgress)exam.planProgress=data.planProgress;data.depthLabel=depthLabels[exam.depth];if(data.finished&&!data.comparison){const grades=exam.messages.filter(m=>m.role==='model'&&m.data.evaluated&&!m.data.finished).map(m=>m.data.score);if((text||audio)&&data.evaluated)grades.push(data.score);if(grades.length){data.sessionAverage=Math.round(grades.reduce((a,b)=>a+b,0)/grades.length*100)/100;data.gradedCount=grades.length}}exam.messages.push({role:'model',data});exam.history.push({role:'model',text:data.speech+'\nDevolución: '+data.feedback});exam.started=true;exam.finished=data.finished;exam.blob=null;exam.recordedTranscript=null;if(sentImage){clearExamImage();examElement('exam-image').value=''}if(exam.blobURL){URL.revokeObjectURL(exam.blobURL);exam.blobURL=null}if(field)field.value='';exam.draft='';if(exam.voice&&examElement('exam-state'))speakProfessor(data.speech)}catch(e){exam.error=e.name==='AbortError'?'El profesor tardó demasiado. Tu respuesta sigue disponible para reintentar.':e.message}finally{exam.busy=false;updateExam();if(!exam.error){const last=examElement('exam-messages')?.lastElementChild;const target=exam.messages.at(-1)?.data?.visual?last?.querySelector('.question-block'):last;target?.scrollIntoView({behavior:'smooth',block:'nearest'})}}}
async function askExam(action){if(exam.busy)return;if(exam.deferredMode&&['answer','finish'].includes(action))return action==='answer'?nextDeferredQuestion():finishDeferredExam();window.examRequest=askExamOnce(action);return window.examRequest}
function downloadExam(){return window.downloadExamText()}

function renderQuestionSpeech(data,index){
 const isCurrent=index===exam.messages.length-1&&!exam.finished;const repeat=`<button class="repeat-question" data-repeat-index="${index}" title="Repetir en voz alta" aria-label="Repetir en voz alta este mensaje">↻</button>`;
 const feedback=data.feedbackSpeech?`<p class="previous-feedback">${esc(data.feedbackSpeech)}</p>`:(!data.question?`<p>${esc(data.speech)}</p>`:'');
 const question=data.question?`<div class="question-block"><div class="question-heading"><span>PREGUNTA</span>${repeat}</div><p class="question-text"><strong>${esc(data.question)}</strong></p></div>`:`<div class="repeat-final">${repeat}</div>`;
 const help=isCurrent&&data.question?`<button class="hint-button" data-hint-index="${index}" ${exam.busy||exam.recording?'disabled':''} aria-expanded="${data.hintOpen?'true':'false'}">💡 ${data.hintUsed?(data.hintOpen?'Ocultar ayuda':'Volver a ver ayuda'):'Ver ayuda visual · −0,50 puntos'}</button>`:'';
 const image=data.hintOpen&&data.hintUrl?`<figure class="visual-hint"><a href="${esc(data.hintUrl)}" target="_blank" rel="noopener" aria-label="Ampliar la ayuda visual"><img src="${esc(data.hintUrl)}" alt="Esquema conceptual de apoyo para el tema de esta pregunta"></a><figcaption>Ayuda conceptual del tema. Descuento de 0,50 puntos en esta respuesta, una sola vez. Tocá el esquema para ampliarlo.</figcaption></figure>`:'';
 return feedback+question+renderVisualExercise(data)+(data.question?questionStatsMarkup(data.questionMeta,data.questionStats):'')+help+image+comparisonMarkup(data.comparison);
}
async function openVisualHint(index){
 const message=exam.messages[index];if(!message||index!==exam.messages.length-1||exam.busy||exam.recording||exam.finished)return;
 if(message.data.hintUsed){message.data.hintOpen=!message.data.hintOpen;updateExam();return}
 exam.busy=true;exam.error='';updateExam();
 try{const response=await fetch('/api/exam',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'hint',subject:exam.subject||currentSubject,unit:exam.unit,scope:exam.scope,speed:exam.speed,level:exam.level,depth:exam.depth,loop:exam.loop,planToken:exam.planToken,history:[]}),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo abrir la ayuda.');if(!/^\/assets\/hints\/(?:unit-\d+|[a-z]+-\d+)\.svg$/.test(data.hintUrl))throw Error('La ayuda no está disponible.');exam.planToken=data.planToken;message.data.hintUrl=data.hintUrl;message.data.hintUsed=true;message.data.hintOpen=true;
 }catch(e){exam.error=e.message||'No se pudo abrir la ayuda.'}finally{exam.busy=false;updateExam();if(!exam.error)examElement('exam-messages')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'start'})}
}

function renderVisualExercise(data){const v=data.visual;if(!v||!/^\/assets\/identificar\/[a-z-]+\.svg$/.test(v.url))return '';return `<figure class="identify-figure"><div class="identify-heading"><span>IDENTIFICAR + EXPLICAR</span><strong>${esc(v.title)}</strong></div><a href="${esc(v.url)}" target="_blank" rel="noopener" aria-label="Ampliar esquema: ${esc(v.title)}"><img src="${esc(v.url)}" alt="${esc(v.title)}: esquema con seis referencias numeradas; identificá las pedidas en la pregunta."></a><figcaption>Respondé por número: nombre y función de cada parte; explicá también sus conexiones y cómo se relacionan en el recorrido del fluido o la energía.${v.targets?.length?' En esta pregunta: '+v.targets.join(', ')+'.':''} Tocá la imagen para ampliarla. Esta lámina forma parte del ejercicio y no descuenta puntos.</figcaption></figure>`}
